  ('g-kentei-h-q33', '6. ディープラーニングの応用例',
   '画像認識のCNNモデルは、性能や設計思想を発展させながら次々と登場してきた。登場した順として最も適切なものはどれか。',
   NULL::text,
   '["AlexNet→VGG→GoogLeNet→ResNet", "VGG→AlexNet→ResNet→GoogLeNet", "GoogLeNet→ResNet→AlexNet→VGG", "ResNet→VGG→GoogLeNet→AlexNet"]',
   0,
   '[0]',
   'single',
   '{"asked": "画像認識CNNモデルの登場順（AlexNet→VGG→GoogLeNet→ResNet）を問うている。", "point": "2012年AlexNet→2014年VGG・GoogLeNet→2015年ResNet、という年の並びで覚える。", "why_asked": "モデル名だけ暗記して登場順や設計思想の変遷を追えていないと、並べ替え系の設問で失点するから。", "kid": "画像を見分けるAIのモデルにも「流行の移り変わり」があり、後から出たモデルほど前のモデルの弱点を直している。", "eg": "スマホが世代ごとに「まずカメラを増やし」「次に軽くし」「次に画面を大きくし」と改良点を変えてきたのと同じで、CNNも「深さ」「並列化」「跳び越し」と改良の切り口を変えてきた。", "terms": [["AlexNet", "2012年の画像認識コンテストで優勝し、深層CNNの有効性を世に示した先駆け"], ["VGG", "小さい3×3フィルタの畳み込みを何層も重ねる、シンプルで深い設計"], ["GoogLeNet", "インセプションモジュール＝大きさ違いの畳み込みを並列に使う構造"], ["ResNet", "スキップ結合(残差接続)で100層を超えても学習できるようにしたモデル"]], "think": "2012年AlexNetがディープラーニングの有効性を実証→2014年、VGG(深さのみで層を積む方向)とGoogLeNet(並列分岐で幅を稼ぐ方向)が同時期に別々のアプローチで登場→2015年ResNetがスキップ結合で「深くしても性能が劣化しない」問題を解決し、以降の標準的な骨格になった。", "vs": "VGGとGoogLeNetは同じ2014年に出たが、VGGは「ひたすら深く積む」方向、GoogLeNetは「並列に分岐させて幅を稼ぐ」方向と、改良の切り口が逆であることを混同しない。", "usecase": "ResNet系は今も画像分類の転移学習のベースモデルとして広く使われている。", "opt": ["正解。2012年にAlexNetが優勝し深層CNNの有効性を示し、2014年にVGGとGoogLeNetが登場、2015年にResNetがスキップ結合で層を深くした、という流れ。", "VGGとAlexNetの順が逆になっている。VGGはAlexNetより後に登場した後継であり、先に来ることはない。", "登場が最も早いAlexNetが最後に来ており、実際の登場順とは大きくずれている。", "スキップ結合で層を深くしたResNetが最初に来ているが、実際にはこの4つの中で最も後発のモデルである。"]}'),

  ('g-kentei-h-q34', '6. ディープラーニングの応用例',
   'GoogLeNetの中核である「インセプションモジュール」が行っていることとして、最も適切なものはどれか。',
   NULL::text,
   '["サイズの異なる複数の畳み込み(1×1・3×3・5×5など)を同じ層内で並列に計算し、その結果をまとめて次の層へ渡す。", "層をいくつか飛び越えて入力をそのまま先の層へ足し込み、非常に深いネットワークでも学習が進むように安定させる仕組みである。", "手元の画像を回転・反転・拡大縮小などで少しずつ変形させ、学習用データを水増しして過学習を抑える仕組みである。", "小さな領域の値を代表値(最大値や平均値)でまとめて、特徴マップの大きさを縮小していく仕組みである。"]',
   0,
   '[0]',
   'single',
   '{"asked": "GoogLeNetのインセプションモジュールが具体的に何をしているかを問うている。", "point": "「サイズ違いの畳み込みを並列に」がインセプションモジュールの本体。", "why_asked": "GoogLeNetの新規性を「深さ」だと誤って覚えると、同時期に出たVGG(深さで勝負)と取り違えるから。", "kid": "1つの層の中で、小さい虫眼鏡・中くらいの虫眼鏡・大きい虫眼鏡を同時に使って画像を見て、その結果を合わせて次に渡すイメージ。", "eg": "料理で「小さく刻む・ざく切りにする・丸ごと使う」を同時に試して、それぞれの下ごしらえの結果を全部まとめて次の工程に回すようなもの。", "terms": [["インセプションモジュール(Inception Module)", "サイズ違いの畳み込みを並列に走らせ、まとめて出力する構造"], ["GoogLeNet", "2014年の画像認識コンテストで優勝したモデル。インセプションモジュールを積み重ねる"], ["1×1畳み込み", "チャネル数を減らして計算量を抑える下ごしらえとして、インセプション内でも使われる"]], "think": "1つのフィルタサイズだけでは「小さい特徴」と「大きい特徴」のどちらかしか拾えない。サイズ違いの畳み込みを並列に置いて結果をまとめれば、1つの層で複数のスケールの特徴を同時に拾える。", "vs": "層を飛び越えて足し込むのはResNetのスキップ結合、小領域を代表値でまとめるのはプーリング層、画像を変形させて水増しするのはデータ拡張であり、いずれもインセプションモジュールとは別の仕組み。", "usecase": "1つの層で複数スケールの特徴を拾いたい場面（物体の大きさが画像ごとにまちまちな認識タスクなど）で有効。", "opt": ["正解。サイズの異なる複数の畳み込みを同じ層内で並列に計算し、その結果をまとめて次の層へ渡すのがインセプションモジュール。", "これはResNetのスキップ結合(残差接続)の説明であり、インセプションモジュールとは別の仕組み。", "これはデータ拡張の説明であり、インセプションモジュールとは無関係。", "これはプーリング層の説明であり、インセプションモジュールとは別の仕組み。"], "viz": "<svg viewBox=\"0 0 340 140\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arr\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#8892a4\"/></marker></defs><text x=\"170\" y=\"13\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">サイズ違いの畳み込みを並列に走らせて合流</text><rect x=\"140\" y=\"30\" width=\"60\" height=\"24\" rx=\"5\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"170\" y=\"46\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">入力</text><line x1=\"150\" y1=\"54\" x2=\"90\" y2=\"74\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arr)\"/><line x1=\"170\" y1=\"54\" x2=\"170\" y2=\"74\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arr)\"/><line x1=\"190\" y1=\"54\" x2=\"250\" y2=\"74\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arr)\"/><rect x=\"60\" y=\"76\" width=\"60\" height=\"24\" rx=\"5\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.3\"/><text x=\"90\" y=\"92\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">1×1</text><rect x=\"140\" y=\"76\" width=\"60\" height=\"24\" rx=\"5\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.3\"/><text x=\"170\" y=\"92\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">3×3</text><rect x=\"220\" y=\"76\" width=\"60\" height=\"24\" rx=\"5\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.3\"/><text x=\"250\" y=\"92\" fill=\"#e8eaf0\" font-size=\"9\" text-anchor=\"middle\">5×5</text><line x1=\"90\" y1=\"100\" x2=\"150\" y2=\"116\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arr)\"/><line x1=\"170\" y1=\"100\" x2=\"170\" y2=\"116\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arr)\"/><line x1=\"250\" y1=\"100\" x2=\"190\" y2=\"116\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arr)\"/><rect x=\"120\" y=\"118\" width=\"100\" height=\"20\" rx=\"5\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.3\"/><text x=\"170\" y=\"132\" fill=\"#6ab08d\" font-size=\"9\" text-anchor=\"middle\" font-weight=\"600\">まとめて次の層へ</text></svg>"}'),

  ('g-kentei-h-q35', '6. ディープラーニングの応用例',
   'DenseNetとSENetの説明の組み合わせとして、最も適切なものはどれか。',
   NULL::text,
   '["DenseNetはある層の出力を後続のすべての層へ直接つなぐ密結合構造を持ち、SENetはチャネルごとの重要度を学習して重み付けする仕組みを持つ。", "DenseNetはチャネルごとの重要度を学習して重み付けする仕組みを持ち、SENetは層を密に結合する構造を持つという、逆の対応関係になっている。", "DenseNetもSENetも、ともに層をいくつか飛び越えて入力をそのまま足し込むだけのスキップ結合の構造で、それ以外の工夫は特に持たない。", "DenseNetもSENetも、ともに畳み込みのサイズを画像内の位置によって変えるだけの構造で、層のつなぎ方には手を加えていない。"]',
   0,
   '[0]',
   'single',
   '{"asked": "DenseNet(密結合)とSENet(チャネルの重み付け)、それぞれの仕組みを取り違えていないかを問うている。", "point": "DenseNetは「層のつなぎ方」、SENetは「チャネルの重み付け」と役割が別。", "why_asked": "名前の響きが似た2つのネットワークの改良ポイントを、逆に覚えてしまう受験者が多いから。", "kid": "DenseNetは「前の作業結果を全員に配る」仕組み、SENetは「今どのチャンネルが役に立っているか」を見て音量調整するような仕組み。", "eg": "DenseNetはグループ作業で各自の成果物を後の全員に配るリレー、SENetはミキサーで各楽器の音量つまみを曲に合わせて自動調整するようなもの。", "terms": [["DenseNet", "各層の出力を後の全ての層に直接つなぐ密結合構造"], ["SENet(Squeeze-and-Excitation Network)", "チャネルごとの重要度を学習し重み付けする仕組み"], ["スキップ結合", "層を飛び越えて入力をそのまま足し込む、ResNetの仕組み"]], "think": "DenseNetは層と層の「つなぎ方」を密にすることで情報の再利用を増やし、勾配も伝わりやすくする。SENetは「どのチャネル(特徴の種類)が今の判断に効いているか」を別に学習し、そこに重みを掛けて強弱をつける。前者は構造、後者はチャネル単位の重み付けという別レイヤーの工夫。", "vs": "DenseNetの密結合とResNetのスキップ結合は「層を飛び越して足す」点で似ているが、DenseNetは全ての後続層につなぐ点がResNetより密である。SENetのチャネル重み付けはこれらの結合構造そのものとは別の軸の工夫。", "usecase": "SENetのチャネル重み付けの発想は他のモデルにも部品として組み込まれることが多い。", "opt": ["正解。DenseNetは密結合構造、SENetはチャネルごとの重要度の重み付けという別々の仕組みを持つ。", "DenseNetとSENetの説明が入れ替わっている。密結合構造を持つのはDenseNet、チャネルの重み付けを行うのはSENetである。", "これはResNetのスキップ結合の説明であり、DenseNetの密結合ともSENetのチャネル重み付けとも異なる。", "畳み込みのサイズを場所によって変える説明はDenseNetにもSENetにも当てはまらない。"]}'),

  ('g-kentei-h-q36', '6. ディープラーニングの応用例',
   'EfficientNet、NAS、MnasNetに共通する考え方として、最も適切なものはどれか。',
   NULL::text,
   '["深さ・幅・解像度をバランスよく同時に大きくする複合スケーリングや、ネットワーク構造そのものを人手でなく自動で探索するという考え方。", "層をいくつか飛び越えて入力をそのまま先の層へ足し込み、非常に深いネットワークでも学習を安定させるという、ResNetのスキップ結合の考え方。", "手元の画像を回転・拡大・縮小などで少しずつ変形させ、学習用データを水増しして過学習を抑えるという、データ拡張の考え方。", "サイズの異なる複数の畳み込みを1つの層の中で並列に走らせ、その結果をまとめて次の層へ渡すという、インセプションの考え方。"]',
   0,
   '[0]',
   'single',
   '{"asked": "EfficientNet・NAS・MnasNetに共通する「モデルの作り方そのものの工夫」を問うている。", "point": "深さ・幅・解像度を同時に調整する／構造自体を自動探索する、がキーワード。", "why_asked": "この3つは「人が手作業で層を設計する」時代から「機械が構造を探す」時代への転換を象徴する用語で、他の性能改善手法(正則化やデータ拡張)と混同されやすいから。", "kid": "今までは人が「ここに何層置くか」を手で決めていたが、この3つは「AIに構造そのものを探させる」「深さ・幅・解像度を全部いっぺんにバランスよく大きくする」という考え方。", "eg": "家を建てるとき、部屋数だけ増やしても住みにくい。天井の高さ・部屋の広さ・部屋数をバランスよく同時に大きくする(EfficientNet)のと、間取りそのものをコンピュータに何百通りも試させて一番良いものを選ばせる(NAS)のに近い。", "terms": [["EfficientNet", "深さ・幅・解像度を同時にバランスよく拡大する複合スケーリングのモデル"], ["NAS(Neural Architecture Search＝ニューラルネットワーク構造探索)", "ネットワークの構造自体を人手でなく自動で探索する手法"], ["MnasNet", "NASをスマホなど端末向けの軽量化の目的で使ったモデル"]], "think": "従来は層の数やフィルタ数を人が経験則で決めていたが、NASはその組み合わせ自体を機械に探索させ、EfficientNetは「深さ・幅・解像度」の3つを決まった比率で同時に増減させることで効率よく性能を伸ばす。MnasNetはこの探索を、スマホでの実行速度も評価軸に入れて行った実例。", "vs": "スキップ結合(ResNet)・データ拡張・インセプションモジュール(GoogLeNet)は「層の中の工夫」だが、この3つは「モデル全体の設計・探索の仕方」という一段上のレイヤーの工夫である点が異なる。", "usecase": "限られた計算資源の中でできるだけ高い精度を狙いたいとき、モデル設計の指針や自動探索の出発点として使われる。", "opt": ["正解。深さ・幅・解像度を同時にバランスよく大きくする考え方と、構造自体を自動探索する考え方が共通する。", "これはResNetのスキップ結合の説明であり、EfficientNet・NAS・MnasNetの共通点ではない。", "これはデータ拡張の説明であり、モデル構造そのものの工夫であるこの3つとは無関係。", "これはGoogLeNetのインセプションモジュールの説明であり、この3つの共通点ではない。"]}'),

  ('g-kentei-h-q37', '6. ディープラーニングの応用例',
   'MobileNetが採用しているDepthwise Separable Convolution(深さ方向分離畳み込み)の狙いとして、最も適切なものはどれか。',
   NULL::text,
   '["通常の畳み込みをチャネルごとの畳み込みと1×1畳み込みに分けて計算し、計算量を大きく減らしてスマホなどの端末上でも動く軽さにする。", "層をいくつか飛び越えて入力をそのまま先の層へ足し込んでおき、非常に深いネットワークでも学習が進むように安定させていく仕組みにすぎない。", "サイズの異なる複数の畳み込みを1つの層の中で並列に走らせておき、その結果をまとめて次の層に渡すようにしていく仕組みにすぎない。", "小さな領域の値をあらかじめ代表値(最大値や平均値)でまとめておき、特徴マップの大きさを縮小していくだけの仕組みにすぎない。"]',
   0,
   '[0]',
   'single',
   '{"asked": "MobileNetの軽量化の仕組み(深さ方向分離畳み込み)が何を減らしているかを問うている。", "point": "「通常の畳み込みを2段階に分けて計算量を削る」がMobileNetの狙い。", "why_asked": "MobileNetの新規性を漠然と「軽い」とだけ覚えると、何をどう軽くしているかを問う設問で答えられないから。", "kid": "普通の畳み込みは「場所も色(チャネル)も同時に」計算するので重い。MobileNetは「まず場所だけ」「次に色の混ぜ合わせだけ」と2段階に分けて計算を軽くする。", "eg": "絵の具を混ぜて塗る作業を、いきなり全色同時に塗るのではなく「まず輪郭を描く」「次に色を重ねる」と分けると、1回あたりの作業が軽くなるのに近い。", "terms": [["Depthwise Separable Convolution(深さ方向分離畳み込み)", "通常の畳み込みを「チャネルごとの畳み込み」と「チャネルを混ぜる1×1畳み込み」に分けて計算量を削る手法"], ["MobileNet", "この分離畳み込みで軽量化し、スマホなど計算資源の少ない端末向けに作られたモデル"]], "think": "通常の畳み込みは「空間方向」と「チャネル方向」を同時に混ぜて計算するため計算量が多い。これを「空間方向だけを畳み込む処理」と「1×1畳み込みでチャネルだけを混ぜる処理」に分けて順番に行うと、同じような表現力をずっと少ない計算量で得られる。", "vs": "GoogLeNetのインセプションモジュール(サイズ違いを並列化)、ResNetのスキップ結合(層を飛び越す)とは狙いが異なり、MobileNetは「1回の畳み込みそのものの計算量」を減らす方向の工夫である点を区別する。", "usecase": "スマホアプリやIoT機器のようにメモリ・電力・計算速度が限られる端末上でリアルタイムに画像認識を動かしたい場面。", "opt": ["正解。通常の畳み込みをチャネルごとの畳み込みと1×1畳み込みに分けて計算量を減らし、端末上でも動く軽さにする。", "これはResNetのスキップ結合の説明であり、MobileNetの深さ方向分離畳み込みとは別の仕組み。", "これはGoogLeNetのインセプションモジュールの説明であり、MobileNetの軽量化とは狙いが異なる。", "これはプーリング層の説明であり、MobileNetの深さ方向分離畳み込みとは別の仕組み。"]}'),

  ('g-kentei-h-q38', '6. ディープラーニングの応用例',
   'FPN(Feature Pyramid Network)が物体検出で果たす役割として、最も適切なものはどれか。',
   NULL::text,
   '["解像度の異なる複数の特徴マップを組み合わせ、大きい物体も小さい物体も同時に検出できるようにする。", "候補領域を提案する処理と種類を判定する処理を1つのネットワークにまとめ上げ、検出を1段階で終える方式にする。", "画像全体を1つの出力ノードに全結合でつなぎ、画像内の位置に関わらず同じ重みで判断できるようにする。", "層をいくつか飛び越えて入力をそのまま先の層へ足し込み、深い層でも学習が進むように安定させる。"]',
   0,
   '[0]',
   'single',
   '{"asked": "FPNが物体検出において何を解決する仕組みかを問うている。", "point": "「解像度違いの特徴マップを重ねて大小の物体を両方拾う」がFPNの核心。", "why_asked": "物体検出は物体の大きさがまちまちなのに、CNNの深い層ほど画像が粗くなり小さい物体の情報が消えやすい、という弱点をFPNがどう補うかが頻出の論点だから。", "kid": "遠くの小さい物体は「細かい層」で、近くの大きい物体は「粗い層」で見る、という具合に、解像度違いの見え方を両方使って検出する仕組み。", "eg": "地図アプリで、広い範囲を見るときはズームアウトした地図、細かい建物を見るときはズームインした地図を両方使い分けるようなもの。", "terms": [["FPN(Feature Pyramid Network＝特徴ピラミッドネットワーク)", "解像度の違う特徴マップを重ね合わせて大小さまざまな物体を検出できるようにする仕組み"], ["特徴マップ", "畳み込みの結果できる、特徴の強さを表す2次元の面"]], "think": "CNNは層が深くなるほど画像は粗くなるが意味の強い特徴を持つ。逆に浅い層は解像度が高いが意味は弱い。FPNは浅い層(細かい・小さい物体向き)と深い層(粗い・大きい物体向き)の両方の特徴マップをピラミッド状に組み合わせて使うことで、物体のサイズによらず検出しやすくする。", "vs": "候補領域の提案と判定を1つにまとめるのはYOLOやSSDのような1段階方式の話であり、FPNは「どの解像度の特徴を使うか」という別の軸の工夫。ResNetのスキップ結合とも役割が異なる。", "usecase": "画像中に遠くの小さい物体と近くの大きい物体が混在する物体検出タスク(自動運転の歩行者・標識検出など)。", "opt": ["正解。解像度の異なる複数の特徴マップを組み合わせ、大きい物体も小さい物体も同時に検出できるようにする。", "これはYOLOやSSDのような1段階方式の物体検出の説明であり、FPNの役割とは別の話。", "これは全結合層の説明であり、FPNとは無関係。", "これはResNetのスキップ結合の説明であり、FPNの役割とは別の仕組み。"], "viz": "<svg viewBox=\"0 0 340 145\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arr\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#8892a4\"/></marker></defs><text x=\"170\" y=\"12\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">解像度の違う特徴マップを重ねて使う</text><rect x=\"255\" y=\"26\" width=\"60\" height=\"20\" rx=\"3\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"285\" y=\"40\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">小(粗い)</text><rect x=\"240\" y=\"54\" width=\"80\" height=\"22\" rx=\"3\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"280\" y=\"69\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">中</text><rect x=\"220\" y=\"84\" width=\"100\" height=\"24\" rx=\"3\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"270\" y=\"100\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">大(細かい)</text><line x1=\"255\" y1=\"36\" x2=\"240\" y2=\"65\" stroke=\"#8892a4\" stroke-width=\"1.3\" stroke-dasharray=\"2 2\"/><line x1=\"240\" y1=\"65\" x2=\"220\" y2=\"96\" stroke=\"#8892a4\" stroke-width=\"1.3\" stroke-dasharray=\"2 2\"/><circle cx=\"50\" cy=\"45\" r=\"6\" fill=\"none\" stroke=\"#c47070\" stroke-width=\"1.3\"/><text x=\"50\" y=\"30\" fill=\"#c47070\" font-size=\"8\" text-anchor=\"middle\">小さい物体</text><line x1=\"56\" y1=\"45\" x2=\"220\" y2=\"96\" stroke=\"#c47070\" stroke-width=\"1.3\" stroke-dasharray=\"3 2\" marker-end=\"url(#arr)\"/><circle cx=\"50\" cy=\"115\" r=\"12\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.3\"/><text x=\"50\" y=\"135\" fill=\"#6ab08d\" font-size=\"8\" text-anchor=\"middle\">大きい物体</text><line x1=\"62\" y1=\"115\" x2=\"255\" y2=\"36\" stroke=\"#6ab08d\" stroke-width=\"1.3\" stroke-dasharray=\"3 2\" marker-end=\"url(#arr)\"/><text x=\"170\" y=\"138\" fill=\"#8892a4\" font-size=\"8.5\" text-anchor=\"middle\">粗い層は大きい物体、細かい層は小さい物体を担当</text></svg>"}'),

  ('g-kentei-h-q39', '6. ディープラーニングの応用例',
   '物体検出のR-CNN→Fast R-CNN→Faster R-CNNという流れと、YOLOやSSDとの違いとして、最も適切なものはどれか。',
   NULL::text,
   '["R-CNN系は候補領域の提案と種類の判定を段階的に行う2段階方式で、YOLOやSSDは両方を1回のネットワークでまとめて行う1段階方式である。", "R-CNN系は候補領域の提案と種類の判定を1回のネットワークでまとめて行う1段階方式であり、YOLOやSSDはそれらを段階的に行う2段階方式である。", "R-CNN系もYOLOやSSDも、どちらも画像の画素一つひとつにクラスラベルを塗り分けるセマンティックセグメンテーションの手法である。", "R-CNN系もYOLOやSSDも、どちらも複数人の関節(肩・肘・膝など)の位置をリアルタイムに推定する姿勢推定の手法である。"]',
   0,
   '[0]',
   'single',
   '{"asked": "R-CNN系(2段階方式)とYOLO・SSD(1段階方式)の違いを問うている。", "point": "「段階を分けるか、1回で済ませるか」が2段階方式と1段階方式の分かれ目。", "why_asked": "同じ物体検出の代表手法でも方式の名前(2段階/1段階)を取り違えると、精度と速度のトレードオフを問う設問で誤答するから。", "kid": "R-CNN系は「まず怪しい場所に印を付けて、次にそこが何かを判定する」の2段構え。YOLOやSSDは「印付けと判定を一度に」済ませる。", "eg": "写真の中から人を探すとき、R-CNN系は「まず人が写ってそうな四角い枠を全部洗い出し、その後1つずつ何が写っているか確認する」やり方、YOLOは「写真全体を一目見て、枠と中身を同時に言い当てる」やり方に近い。", "terms": [["R-CNN", "候補領域を提案してから種類を判定する、2段階方式の物体検出の元祖"], ["Fast R-CNN / Faster R-CNN", "R-CNNの計算の重複や候補領域の作り方を段階的に高速化した後継"], ["1段階方式(YOLO・SSD)", "候補提案と判定を1回のネットワークで済ませ、検出を高速化した方式"]], "think": "R-CNNはまず画像から候補領域(怪しい場所)を大量に切り出し、その一つ一つをCNNに通して種類を判定する2段階の処理だった。Fast R-CNN・Faster R-CNNは候補領域の作り方や計算の重複を段階的に高速化したが、2段階という構造自体は保っている。YOLOやSSDはこの2段階を1本のネットワークにまとめ、画像を1回見るだけで枠と種類を同時に出す1段階方式にして、速度を優先した。", "vs": "2段階方式(R-CNN系)は一般に精度で有利、1段階方式(YOLO・SSD)は速度で有利という一般的な傾向があり、「段階を分けるかどうか」という構造の違いを取り違えないこと。", "usecase": "精度優先なら2段階方式、リアルタイム性優先(監視カメラや自動運転)なら1段階方式、と用途で使い分けられる。", "opt": ["正解。R-CNN系は候補領域の提案と判定を2段階で行い、YOLOやSSDは両方を1回のネットワークでまとめて行う1段階方式である。", "R-CNN系とYOLO・SSDの方式の説明が入れ替わっている。2段階方式はR-CNN系、1段階方式はYOLOやSSDである。", "これはセマンティックセグメンテーションの説明であり、いずれも物体検出とは別のタスクである。", "これは姿勢推定の説明であり、いずれも物体検出とは別のタスクである。"]}'),

  ('g-kentei-h-q40', '6. ディープラーニングの応用例',
   'FCN、SegNet、PSPNet、DeepLabの4つに共通する説明として、最も適切なものはどれか。',
   NULL::text,
   '["いずれも画像の画素一つひとつにクラスラベルを割り当てる、セマンティックセグメンテーションの手法である。", "いずれも画像中の物体それぞれを囲む枠(バウンディングボックス)の位置と種類を求める、物体検出の手法である。", "いずれも人物の関節(肩・肘・膝など)の位置を同時にリアルタイムに推定する、姿勢推定の手法である。", "いずれもノイズを少しずつ段階的に取り除いて画像を新しく作り出す、データ生成の手法である。"]',
   0,
   '[0]',
   'single',
   '{"asked": "FCN・SegNet・PSPNet・DeepLabという名前が、どのタスクの一族に属するかを問うている。", "point": "この4つはすべて「画素単位でラベルを付ける」セマンティックセグメンテーションの手法群。", "why_asked": "似た響きのモデル名が並ぶと、物体検出やデータ生成など別タスクの手法と混同しやすいから。", "kid": "FCN・SegNet・PSPNet・DeepLabは、どれも写真の1マス1マすに「これは道」「これは車」と色を塗り分けていく仲間。", "eg": "塗り絵で、輪郭で囲んだ「枠」だけを答えるのではなく、マス目1つ1つに色を塗っていくようなもの。この4つはその塗り分けの精度を上げる工夫が違うだけで、目指すこと自体は同じ。", "terms": [["FCN(Fully Convolutional Network)", "全結合層を使わず畳み込みだけで画素ごとのラベルを出力する、セマンティックセグメンテーションの草分け"], ["SegNet / PSPNet / DeepLab", "画像を段階的に縮めてから元の大きさに戻す、などの工夫でFCNを発展させた後継の手法群"], ["セマンティックセグメンテーション", "画像の画素一つひとつにクラスラベルを付けるタスク"]], "think": "この4つはいずれも「画像を入力し、同じ大きさの画素ごとのラベル画像を出力する」という同じ目的を持つ。FCNが全結合層を使わない構造で先陣を切り、SegNet・PSPNet・DeepLabはそれぞれ違う工夫(縮小と復元の仕方、広い範囲の文脈の取り込み方など)でこの目的の精度を高めた後継にあたる。", "vs": "物体検出(枠と種類)、姿勢推定(関節位置)、データ生成(新しい画像を作る)とは目的が異なるタスクであり、この4つはあくまで「画素単位の塗り分け」という同じ土俵の手法である点を混同しない。", "usecase": "自動運転の走行可能領域の把握や、医療画像で病変部分を画素単位で特定する場面など。", "opt": ["正解。いずれも画像の画素一つひとつにクラスラベルを割り当てる、セマンティックセグメンテーションの手法である。", "これは物体検出の説明であり、FCN・SegNet・PSPNet・DeepLabはいずれも画素単位のラベル付けを行う別のタスクの手法である。", "これは姿勢推定の説明であり、この4つとは異なるタスクである。", "これはデータ生成の説明であり、この4つとは異なるタスクである。"]}'),

  ('g-kentei-h-q41', '6. ディープラーニングの応用例',
   'パノプティックセグメンテーションが表す内容として、最も適切なものはどれか。',
   NULL::text,
   '["道路や空のような数えられない背景はクラスだけで塗り分け、人や車のような数えられる物体は個体ごとに区別する、セマンティックとインスタンスの両方を統合した表現。", "画像全体に対して「これは猫の写真」のように、画素単位の細かいラベルはまったく付けずに、1枚に1つのラベルだけを付けて済ませる、画像分類だけの表現にすぎない。", "画像中の物体それぞれを囲む枠の位置とクラスだけを求めておき、画素単位の細かいラベルは一切付けない、物体検出だけの表現にすぎない。", "同じ「人」というクラスに属する画素をひとまとめにして塗り分けるだけで、個体ごとの区別は一切行わない、セマンティックのみの表現にすぎない。"]',
   0,
   '[0]',
   'single',
   '{"asked": "パノプティックセグメンテーションが、セマンティックセグメンテーションとインスタンスセグメンテーションのどちらの性質も持つ統合表現であることを問うている。", "point": "背景はクラスだけ、物体は個体ごと、という2つの塗り分け方を1枚に統合したのがパノプティック。", "why_asked": "「セマンティック」「インスタンス」「パノプティック」という似た名前の3つを、それぞれ何を区別し何を区別しないかで正確に弁別できるかが頻出の引っかけだから。", "kid": "空や道路のような「数えられないもの」は色だけ塗り、人や車のような「数えられるもの」は1人ずつ・1台ずつ別の色で塗り分ける、という両方をやる塗り分け方。", "eg": "教室の集合写真で、黒板や床は「黒板」「床」とだけラベルを付ければ十分だが、生徒は「Aさん」「Bさん」と1人ずつ区別したい。その両方を1枚の絵でやるのがパノプティック。", "terms": [["セマンティックセグメンテーション", "画素ごとにクラスだけを塗り分け、同じクラスの個体を区別しない"], ["インスタンスセグメンテーション", "同じクラスでも個体ごとに別領域として区別する"], ["パノプティックセグメンテーション", "数えられない背景はクラスだけ、数えられる物体は個体ごとに区別、という両方を統合した表現"]], "think": "セマンティックセグメンテーションは「クラスだけ」を塗り分けるので、同じ「人」が3人写っていても区別しない。インスタンスセグメンテーションは逆に「物体(数えられるもの)」だけを個体ごとに区別するが、道路や空のような背景は扱いが甘くなりがち。パノプティックセグメンテーションは、背景はクラスだけで塗り、物体は個体ごとに区別するという、両者のいいとこ取りをした表現。", "vs": "セマンティック(クラスのみ)、インスタンス(数えられる物体のみを個体区別)、パノプティック(両方を統合)という3段階の違いを取り違えない。", "usecase": "自動運転や画像理解で、道路のような背景と、歩行者1人1人のような個体の両方を同時に正確に把握したい場面。", "opt": ["正解。数えられない背景はクラスだけ、数えられる物体は個体ごとに区別する、セマンティックとインスタンスを統合した表現。", "これは画像分類(1枚に1つのラベルを付けるタスク)の説明であり、パノプティックセグメンテーションとは別のタスク。", "これは物体検出の説明であり、画素単位のラベルを持たない点でパノプティックセグメンテーションとは異なる。", "これはセマンティックセグメンテーションだけの説明であり、個体ごとの区別を行わない点がパノプティックとは異なる。"], "viz": "<svg viewBox=\"0 0 340 158\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><text x=\"170\" y=\"12\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">背景と物体、両方の塗り分け方を比べる</text><text x=\"55\" y=\"22\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">セマンティック</text><rect x=\"5\" y=\"28\" width=\"100\" height=\"50\" rx=\"4\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><rect x=\"13\" y=\"58\" width=\"84\" height=\"14\" rx=\"2\" fill=\"#c9a04a\" stroke=\"#c9a04a\" stroke-width=\"1.3\" opacity=\"0.35\"/><circle cx=\"35\" cy=\"46\" r=\"8\" fill=\"#60a5fa\" stroke=\"#60a5fa\" stroke-width=\"1.3\" opacity=\"0.4\"/><circle cx=\"70\" cy=\"46\" r=\"8\" fill=\"#60a5fa\" stroke=\"#60a5fa\" stroke-width=\"1.3\" opacity=\"0.4\"/><text x=\"55.0\" y=\"91\" fill=\"#8892a4\" font-size=\"7.5\" text-anchor=\"middle\">同じ色で塗るだけ</text><text x=\"55.0\" y=\"103\" fill=\"#8892a4\" font-size=\"7.5\" text-anchor=\"middle\">(個体は区別しない)</text><text x=\"175\" y=\"22\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">インスタンス</text><rect x=\"120\" y=\"28\" width=\"100\" height=\"50\" rx=\"4\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><rect x=\"128\" y=\"58\" width=\"84\" height=\"14\" rx=\"2\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><circle cx=\"150\" cy=\"46\" r=\"8\" fill=\"#60a5fa\" stroke=\"#60a5fa\" stroke-width=\"1.3\" opacity=\"0.55\"/><circle cx=\"185\" cy=\"46\" r=\"8\" fill=\"#6ab08d\" stroke=\"#6ab08d\" stroke-width=\"1.3\" opacity=\"0.55\"/><text x=\"170.0\" y=\"91\" fill=\"#8892a4\" font-size=\"7.5\" text-anchor=\"middle\">物体だけ</text><text x=\"170.0\" y=\"103\" fill=\"#8892a4\" font-size=\"7.5\" text-anchor=\"middle\">個体ごとに色分け</text><text x=\"285\" y=\"22\" fill=\"#6ab08d\" font-size=\"8\" text-anchor=\"middle\">パノプティック</text><rect x=\"235\" y=\"28\" width=\"100\" height=\"50\" rx=\"4\" fill=\"none\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><rect x=\"243\" y=\"58\" width=\"84\" height=\"14\" rx=\"2\" fill=\"#c9a04a\" stroke=\"#c9a04a\" stroke-width=\"1.3\" opacity=\"0.35\"/><circle cx=\"265\" cy=\"46\" r=\"8\" fill=\"#60a5fa\" stroke=\"#60a5fa\" stroke-width=\"1.3\" opacity=\"0.55\"/><circle cx=\"300\" cy=\"46\" r=\"8\" fill=\"#6ab08d\" stroke=\"#6ab08d\" stroke-width=\"1.3\" opacity=\"0.55\"/><text x=\"285.0\" y=\"91\" fill=\"#6ab08d\" font-size=\"7.5\" text-anchor=\"middle\">背景はクラスのみ</text><text x=\"285.0\" y=\"103\" fill=\"#6ab08d\" font-size=\"7.5\" text-anchor=\"middle\">物体は個体で区別</text></svg>"}'),

  ('g-kentei-h-q42', '6. ディープラーニングの応用例',
   'OpenPoseが行うタスクとして、最も適切なものはどれか。',
   NULL::text,
   '["画像や映像から複数人の関節位置をリアルタイムに推定し、体の姿勢をとらえる。", "画像の画素一つひとつに、それがどのクラスに属するかのラベルを割り当てて塗り分ける。", "画像に写る物体それぞれについて、それを囲む枠の位置と種類を同時に求める。", "文章を意味のある単語(形態素)ごとに区切り、それぞれの品詞などを判定する。"]',
   0,
   '[0]',
   'single',
   '{"asked": "OpenPoseが「姿勢推定」の手法であり、セグメンテーションや物体検出、自然言語処理とは別物であることを問うている。", "point": "OpenPose＝複数人の関節位置をリアルタイムに推定する姿勢推定の代表手法。", "why_asked": "画像認識の応用例が並ぶと、名前だけ見てセグメンテーション系や物体検出系の手法と混同しやすいから。", "kid": "写真や映像に写っている人の肩・肘・膝・足首といった関節の位置を見つけて、その人がどんなポーズを取っているかを当てる仕組み。", "eg": "ダンスの動画を見て、関節に印を付けて棒人間の絵に描き起こすようなもの。1人だけでなく、複数人が写っていても同時にできる。", "terms": [["OpenPose", "複数人の関節(肩・肘・膝など)の位置を同時にリアルタイム推定する手法"], ["姿勢推定(Pose Estimation)", "画像・映像から人の体の関節位置をとらえるタスク全般"]], "think": "OpenPoseは画像・映像の中から人の体の各関節の位置を検出し、それらをつなげて骨格(スケルトン)として表現する。複数人が同時に写っていても、それぞれの人物ごとに関節をまとめて推定できる点が特徴。", "vs": "画素単位でクラスを塗り分けるのはセマンティックセグメンテーション、枠と種類を求めるのは物体検出、文章を単語に分けるのは形態素解析であり、いずれもOpenPoseとは対象(画像か文章か)もタスクも異なる。", "usecase": "スポーツフォームの解析、モーションキャプチャ不要の動作認識、監視カメラでの不審行動の検知など。", "opt": ["正解。画像や映像から複数人の関節位置をリアルタイムに推定し、体の姿勢をとらえる。", "これはセマンティックセグメンテーションの説明であり、OpenPoseの姿勢推定とは別のタスク。", "これは物体検出の説明であり、OpenPoseの姿勢推定とは別のタスク。", "これは形態素解析の説明であり、対象が文章である点でOpenPose(画像・映像が対象)とは全く異なる。"]}'),

  ('g-kentei-h-q43', '6. ディープラーニングの応用例',
   'BoW(Bag-of-Words)とN-gramの違いとして、最も適切なものはどれか。',
   NULL::text,
   '["BoWは文中の単語の出現回数だけを数え語順を無視するのに対し、N-gramは連続するN個の単語のまとまりを見て語順の情報をある程度保持する。", "BoWは連続するN個の単語のまとまりを見て語順をある程度保持するのに対し、N-gramは単語の出現回数だけを数えて語順をまったく無視する。", "BoWもN-gramも、どちらも単語を意味の近さが距離に反映される密なベクトルに変換する、word2vecのような埋め込みの手法にすぎない。", "BoWもN-gramも、どちらも文中に出てくる未知語をさらに小さなサブワードに分解して扱う、fastTextのような手法にすぎない。"]',
   0,
   '[0]',
   'single',
   '{"asked": "BoW(単語を数えるだけ・語順無視)とN-gram(連続するN語のまとまり・語順をある程度保持)の違いを問うている。", "point": "「語順を捨てるか、少しだけ保持するか」がBoWとN-gramの分かれ目。", "why_asked": "word2vec以前の古典的な文章の数値表現として並べて出やすく、語順を扱えるかどうかの違いを取り違えやすいから。", "kid": "BoWは「文に出てきた単語を袋に放り込んで数を数えるだけ」で並び順は見ない。N-gramは「隣り合う単語をひとかたまりにして数える」ので、少しだけ並び順の情報が残る。", "eg": "BoWは買い物かごの中身を「りんご2個、みかん1個」と数えるだけで、どちらを先にかごに入れたかは気にしない。N-gramは「りんごの次にみかんを入れた」という隣り合わせの組も記録するイメージ。", "terms": [["BoW(Bag-of-Words＝単語の袋)", "文を単語の出現回数だけで表し、語順の情報を捨てる古典的な表現"], ["N-gram", "連続するN個の単語(や文字)のまとまりを1単位として数える表現。語順をある程度保持する"]], "think": "BoWは「どの単語が何回出てきたか」という頻度の情報だけを持つ表現で、文の中でどの順番に並んでいたかは失われる。N-gram(例えばN=2のバイグラム)は「隣り合う2語の組」を1つの単位として数えるので、「単語Aの次に単語Bが来た」という語順の一部の情報を残せる。", "vs": "word2vecのように意味の近さを密なベクトルの距離で表す手法とは全く別で、BoW・N-gramはあくまで「単語の出現をどう数えるか」という数え方の違いにとどまる。", "usecase": "文書分類やスパム判定のように、語順の細かい情報よりも「どの単語が多く出てくるか」が重要な場面ではBoWで十分なことが多い。", "opt": ["正解。BoWは単語の出現回数だけを数え語順を無視し、N-gramは連続するN個の単語のまとまりで語順をある程度保持する。", "BoWとN-gramの説明が入れ替わっている。語順を無視するのはBoW、連続するまとまりで語順を保持するのはN-gramである。", "これはword2vecのような単語埋め込みの説明であり、BoW・N-gramとは別の枠組み。", "これはfastTextのようなサブワード分解の説明であり、BoW・N-gramとは別の枠組み。"]}'),

  ('g-kentei-h-q44', '6. ディープラーニングの応用例',
   'word2vecの2つの学習方式であるCBOWとスキップグラムの違いとして、最も適切なものはどれか。',
   NULL::text,
   '["CBOWは周囲の単語から中心の単語を予測し、スキップグラムは中心の単語から周囲の単語を予測する。", "CBOWは中心の単語から周囲の単語を予測し、スキップグラムは周囲の単語から中心の単語を予測する。", "CBOWもスキップグラムも、どちらも文中の単語の出現回数だけを数え語順を無視する。", "CBOWもスキップグラムも、どちらも未知語をさらに小さなサブワードに分解して扱う。"]',
   0,
   '[0]',
   'single',
   '{"asked": "CBOW(周囲→中心)とスキップグラム(中心→周囲)の予測の向きの違いを問うている。", "point": "「周囲から中心か、中心から周囲か」という予測方向の違いが分かれ目。", "why_asked": "同じword2vecの2つの学習方式として並べて出やすく、名前の向きと予測の向きを逆に覚えてしまいやすいから。", "kid": "CBOWは「まわりの単語を見て、真ん中に何が入るか当てる」クイズ。スキップグラムは逆に「真ん中の単語を見て、まわりに何が来るか当てる」クイズ。", "eg": "CBOWは「〇〇に　を　食べた」の空欄に入る単語を、前後の言葉から当てるクイズ。スキップグラムは「りんご」という単語だけを見せられて、その前後にどんな単語が来そうかを当てるクイズ。", "terms": [["CBOW(Continuous Bag-of-Words)", "周囲の単語から中心の単語を予測する学習方式"], ["スキップグラム(Skip-gram)", "中心の単語から周囲の単語を予測する学習方式"], ["word2vec", "単語を密なベクトルに変換する手法。CBOWとスキップグラムという2つの学習方式を持つ"]], "think": "word2vecは「単語の意味は周囲の単語との共起関係から決まる」という考え方に基づく。CBOWは周囲の複数の単語を手がかりに中心の1語を当てる問題として学習し、スキップグラムは逆に中心の1語を手がかりに周囲の複数語を当てる問題として学習する。どちらも最終的には似た意味の単語が近いベクトルになるよう学習される。", "vs": "BoW・N-gramは単語を「数える」表現、CBOW・スキップグラムは単語を「密なベクトルに埋め込む」表現であり、そもそも土俵が異なる。CBOWとスキップグラムの間では予測の向きだけが違う点を混同しない。", "usecase": "類義語の検索やレコメンドで「意味が近い単語」をベクトルの距離で扱いたい場面の土台になる。", "opt": ["正解。CBOWは周囲の単語から中心の単語を予測し、スキップグラムは中心の単語から周囲の単語を予測する。", "CBOWとスキップグラムの予測の向きが入れ替わっている。周囲→中心はCBOW、中心→周囲はスキップグラムである。", "これはBoWの説明であり、CBOW・スキップグラムのような密なベクトルへの埋め込みとは別の枠組み。", "これはfastTextの説明であり、CBOW・スキップグラムの予測方向の違いとは別の話。"], "viz": "<svg viewBox=\"0 0 340 135\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arr\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#8892a4\"/></marker></defs><text x=\"170\" y=\"13\" fill=\"#e8eaf0\" font-size=\"10.5\" text-anchor=\"middle\" font-weight=\"600\">予測する向きが逆</text><text x=\"85\" y=\"28\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">CBOW</text><circle cx=\"50\" cy=\"55\" r=\"5\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><text x=\"50\" y=\"72\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">周囲</text><circle cx=\"120\" cy=\"55\" r=\"5\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><text x=\"120\" y=\"72\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">周囲</text><circle cx=\"85\" cy=\"90\" r=\"6\" fill=\"#6ab08d\" stroke=\"#6ab08d\" stroke-width=\"1.3\" opacity=\"0.5\"/><text x=\"85\" y=\"108\" fill=\"#6ab08d\" font-size=\"8\" text-anchor=\"middle\">中心</text><line x1=\"50\" y1=\"60\" x2=\"78\" y2=\"85\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arr)\"/><line x1=\"120\" y1=\"60\" x2=\"92\" y2=\"85\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arr)\"/><text x=\"85\" y=\"122\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">周囲→中心を予測</text><line x1=\"170\" y1=\"20\" x2=\"170\" y2=\"118\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><text x=\"255\" y=\"28\" fill=\"#60a5fa\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">スキップグラム</text><circle cx=\"255\" cy=\"90\" r=\"6\" fill=\"#6ab08d\" stroke=\"#6ab08d\" stroke-width=\"1.3\" opacity=\"0.5\"/><text x=\"255\" y=\"108\" fill=\"#6ab08d\" font-size=\"8\" text-anchor=\"middle\">中心</text><circle cx=\"220\" cy=\"55\" r=\"5\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><text x=\"220\" y=\"72\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">周囲</text><circle cx=\"290\" cy=\"55\" r=\"5\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><text x=\"290\" y=\"72\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">周囲</text><line x1=\"255\" y1=\"85\" x2=\"227\" y2=\"60\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arr)\"/><line x1=\"255\" y1=\"85\" x2=\"283\" y2=\"60\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arr)\"/><text x=\"255\" y=\"122\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">中心→周囲を予測</text></svg>"}'),

  ('g-kentei-h-q45', '6. ディープラーニングの応用例',
   'fastTextとGLUEの説明の組み合わせとして、最も適切なものはどれか。',
   NULL::text,
   '["fastTextは単語をさらに小さなサブワードに分解して扱うことで未知語にも対応しやすくした手法であり、GLUEは複数の自然言語処理タスクをまとめて評価するベンチマークである。", "fastTextは複数の自然言語処理タスクをまとめて評価するベンチマークであり、GLUEは単語をさらに小さなサブワードに分解して未知語に対応しやすくする手法である、という逆の対応関係になっている。", "fastTextもGLUEも、どちらも文中に出てくる単語の出現回数だけを数える、語順を無視した古典的な表現手法にすぎない。", "fastTextもGLUEも、どちらも周囲の単語から中心の単語を予測する、word2vecの学習方式の一種にすぎない。"]',
   0,
   '[0]',
   'single',
   '{"asked": "fastText(サブワード分解の単語埋め込み手法)とGLUE(評価ベンチマーク)を正しく対応づけられるかを問うている。", "point": "fastTextは「単語の作り方」の工夫、GLUEは「モデルの実力を測るものさし」。", "why_asked": "どちらも自然言語処理の頻出用語だが、片方は手法、片方は評価基準というカテゴリの違う概念で、セットで問われると混同しやすいから。", "kid": "fastTextは知らない単語が出てきても、その単語の一部分(部品)から意味を推測できるようにした仕組み。GLUEは色々な国語のテストをまとめたテストセットのようなもので、AIの実力を測るために使う。", "eg": "fastTextは知らない英単語でも「接頭辞・語幹・接尾辞」から意味を推測する読み方の工夫。GLUEは複数科目(読解・穴埋め・言い換え判定など)をまとめた模擬試験セットのようなもの。", "terms": [["fastText", "単語をさらに小さな部品(サブワード)に分解して扱い、辞書にない未知語にも強い単語埋め込み手法"], ["GLUE(General Language Understanding Evaluation)", "複数の自然言語処理タスクをまとめて評価する代表的なベンチマーク"]], "think": "word2vecは単語をまるごと1つの単位として扱うため、学習データに無かった単語(未知語)を扱えない。fastTextは単語をさらに小さなサブワードに分解して埋め込むことで、未知語でも部分的な情報から近い意味のベクトルを作れるようにした。一方GLUEはモデルそのものの手法ではなく、複数の言語理解タスクをひとまとめにして性能を比較するための「ものさし」である。", "vs": "fastText・word2vecは「単語をベクトルに変換する手法」というグループ、GLUEは「モデルの性能を評価するベンチマーク」というグループで、そもそも役割のカテゴリが違う点を混同しない。", "usecase": "fastTextはSNSの投稿のように誤字や造語が多い文章の解析、GLUEは新しく作った言語モデルの実力を客観的に比較する場面で使われる。", "opt": ["正解。fastTextはサブワードに分解して未知語に対応する手法であり、GLUEは複数タスクをまとめて評価するベンチマークである。", "fastTextとGLUEの説明が入れ替わっている。サブワード分解の手法はfastText、評価ベンチマークはGLUEである。", "これはBoWの説明であり、fastText・GLUEのどちらの説明でもない。", "これはCBOWの説明であり、fastText・GLUEのどちらの説明でもない。"]}'),

  ('g-kentei-h-q46', '6. ディープラーニングの応用例',
   '音声をコンピュータで扱うためのデジタル化の流れとして、最も適切なものはどれか。',
   NULL::text,
   '["A-D変換で連続的な波形を一定間隔でサンプリングしてPCM(パルス符号変調)の数値列にし、必要に応じてFFT(高速フーリエ変換)で周波数成分に分解する。", "FFTで波形を先に一定間隔で数値の列に変えておいた後で、A-D変換でその数値列を周波数ごとの成分に分解する、という実際とは逆の順序で処理を進めていく。", "PCMは音声を周波数ごとの成分に分解しておく処理を指す用語であり、A-D変換はその周波数成分の結果を元の連続的な波形へと戻していく処理を指す用語にすぎない。", "音声のデジタル化は、隠れマルコフモデル(HMM)という古典的な仕組みだけが波形をラベルへ直接変換していく、たった1段階だけの処理にすぎない。"]',
   0,
   '[0]',
   'single',
   '{"asked": "音声のデジタル化が「A-D変換→PCM→(必要ならFFTで周波数へ)」という順で進むことを問うている。", "point": "波形→数値(PCM)→周波数(FFT)、という順番を入れ替えない。", "why_asked": "A-D変換・PCM・FFT・HMMという用語が並ぶと、どれがどの段階の処理かを取り違えやすいから。", "kid": "マイクが拾った「なめらかな波」を、一定間隔で区切って数字の列にするのがA-D変換とPCM。そこからさらに「どんな高さの音がどれくらい混ざっているか」を調べるのがFFT。", "eg": "アナログ時計の針の動き(なめらかな波)を、1分ごとに数字で記録していく(A-D変換・PCM)。その記録した数字の並びを見て「このリズムにはどんな周期の変化が混ざっているか」を分析する(FFT)、という2段階の作業に近い。", "terms": [["A-D変換(アナログ-デジタル変換)", "連続的な波形を一定間隔で区切って数値化する処理"], ["PCM(Pulse Code Modulation＝パルス符号変調)", "A-D変換で得た数値をそのまま並べた、音声のデジタル表現"], ["FFT(Fast Fourier Transform＝高速フーリエ変換)", "波形を周波数ごとの成分に分解する計算"], ["隠れマルコフモデル(HMM)", "音声認識で、音の並びの変化を確率的な状態遷移として扱った古典的なモデル"]], "think": "マイクが拾う音はもともと連続的な波形(アナログ)なので、そのままではコンピュータで扱えない。まずA-D変換で一定間隔ごとに波の高さを数値化し、その数値の並びをPCMと呼ぶ。ここまでで「波形のデジタル表現」ができるが、音の高さの成分を調べたいときはさらにFFTで周波数ごとの強さに分解する。HMMはこの後の段階で、音の並びの時間的な変化を確率的な状態の移り変わりとして扱う古典的な音声認識モデル。", "vs": "PCMは「波形を数値化したもの」、FFTは「その数値を周波数に分解する計算」であり、両者の役割を入れ替えない。HMMはさらに後段の「認識」の話であり、A-D変換・PCM・FFTという「前処理」の段階とは別レイヤー。", "usecase": "音声アシスタントや文字起こしサービスで、マイクの音をテキストに変換する処理の最初の下ごしらえとして必ず通る工程。", "opt": ["正解。A-D変換で波形を数値化してPCMにし、必要ならFFTで周波数成分に分解するという流れ。", "A-D変換とFFTの役割が入れ替わっている。波形を数値化するのはA-D変換であり、その数値を周波数に分解するのがFFTである。", "PCMとA-D変換の役割の説明が誤っている。PCMは数値化された音声表現そのものであり、周波数に分解する処理ではない。", "HMMは音の並びの変化を確率的に扱う認識段階のモデルであり、波形からラベルへの1段階の変換だけを行うものではない。"], "viz": "<svg viewBox=\"0 0 340 135\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arr\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#8892a4\"/></marker></defs><text x=\"170\" y=\"12\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">波形→数値→周波数、という3段の流れ</text><path d=\"M15 60 C 30 30, 45 90, 60 60 C 75 30, 90 90, 105 60\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.5\"/><text x=\"60\" y=\"80\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">波形</text><line x1=\"112\" y1=\"60\" x2=\"140\" y2=\"60\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arr)\"/><text x=\"126\" y=\"50\" fill=\"#c9a04a\" font-size=\"7.5\" text-anchor=\"middle\">A-D変換</text><circle cx=\"150\" cy=\"45\" r=\"2\" fill=\"#60a5fa\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><circle cx=\"150\" cy=\"60\" r=\"2\" fill=\"#60a5fa\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><circle cx=\"150\" cy=\"75\" r=\"2\" fill=\"#60a5fa\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><circle cx=\"162\" cy=\"50\" r=\"2\" fill=\"#60a5fa\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><circle cx=\"162\" cy=\"68\" r=\"2\" fill=\"#60a5fa\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"156\" y=\"90\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">PCM(数値列)</text><line x1=\"178\" y1=\"60\" x2=\"206\" y2=\"60\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arr)\"/><text x=\"192\" y=\"50\" fill=\"#c9a04a\" font-size=\"7.5\" text-anchor=\"middle\">FFT</text><rect x=\"215\" y=\"70\" width=\"8\" height=\"20\" rx=\"4\" fill=\"#6ab08d\" stroke=\"#6ab08d\" stroke-width=\"1.3\" opacity=\"0.4\"/><rect x=\"226\" y=\"50\" width=\"8\" height=\"40\" rx=\"4\" fill=\"#6ab08d\" stroke=\"#6ab08d\" stroke-width=\"1.3\" opacity=\"0.4\"/><rect x=\"237\" y=\"62\" width=\"8\" height=\"28\" rx=\"4\" fill=\"#6ab08d\" stroke=\"#6ab08d\" stroke-width=\"1.3\" opacity=\"0.4\"/><rect x=\"248\" y=\"75\" width=\"8\" height=\"15\" rx=\"4\" fill=\"#6ab08d\" stroke=\"#6ab08d\" stroke-width=\"1.3\" opacity=\"0.4\"/><text x=\"240\" y=\"100\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">周波数成分</text><text x=\"170\" y=\"122\" fill=\"#8892a4\" font-size=\"8\" text-anchor=\"middle\">HMMは、この後の音の並びの変化を確率で扱う仕組み</text></svg>"}'),

  ('g-kentei-h-q47', '6. ディープラーニングの応用例',
   'DQNの学習を安定させるために導入された、経験再生とターゲットネットワークの役割の組み合わせとして、最も適切なものはどれか。',
   NULL::text,
   '["経験再生は過去の経験をため込みランダムに取り出して学習することでデータの偏りを減らし、ターゲットネットワークは学習目標値を計算する側のネットワークを一定間隔だけ固定して更新の振動を抑える。", "経験再生は学習目標値を計算するネットワークを一定間隔だけ固定して更新の振動を抑える仕組みであり、ターゲットネットワークは過去の経験をため込んでランダムに取り出して学習に使っていく仕組みである。", "経験再生もターゲットネットワークも、どちらも複数のエージェントを非同期に並行して同時に学習させる、マルチエージェント学習のための仕組みにすぎない。", "経験再生もターゲットネットワークも、どちらも人があとから報酬の与え方を細かく調整して学習を導いていく、報酬成形と呼ばれる手法にすぎない。"]',
   0,
   '[0]',
   'single',
   '{"asked": "DQNを安定させる2つの工夫(経験再生とターゲットネットワーク)の役割を取り違えていないかを問うている。", "point": "経験再生は「データの偏り対策」、ターゲットネットワークは「目標値のブレ対策」。", "why_asked": "DQNの安定化の工夫としてセットで語られやすく、どちらが何を安定させているかを逆に覚えてしまう受験者が多いから。", "kid": "経験再生は「最近の出来事だけでなく昔の経験もランダムに混ぜて復習する」工夫。ターゲットネットワークは「お手本の答えをコロコロ変えない」ように、お手本役をしばらく固定しておく工夫。", "eg": "経験再生はノートに書きためた過去の失敗例からランダムに問題を選んで復習するようなもの。ターゲットネットワークは、テストの模範解答を毎回コロコロ変えず、一定期間は同じ模範解答を使い続けるようなもの。", "terms": [["経験再生(Experience Replay)", "過去の経験を蓄えておき、そこからランダムに取り出して学習に使う仕組み。時系列の偏りを減らす"], ["ターゲットネットワーク", "学習の目標値を計算する側のネットワークを一定間隔だけ固定し、更新が暴れるのを防ぐ仕組み"], ["DQN(Deep Q-Network)", "Q値をニューラルネットワークで近似する深層強化学習の代表手法"]], "think": "強化学習では直近の経験ばかりを順番に学習すると、データの並びに偏りが出て学習が不安定になる。経験再生は過去の経験をまとめてため込み、そこからランダムに取り出すことでこの偏りを減らす。また学習の目標値(正解に相当する値)を計算するネットワークが、今まさに更新中のネットワークと同じだと、目標自体がコロコロ動いて学習が発散しやすい。ターゲットネットワークはこの目標値を計算する側を一定間隔だけ固定することで、学習を安定させる。", "vs": "マルチエージェントは複数の学習主体を同時に扱う話、報酬成形は報酬の与え方を人が調整する話であり、いずれも経験再生・ターゲットネットワークとは別の工夫。", "usecase": "ゲームAIのように試行錯誤で学習するとき、限られた経験を無駄なく再利用しつつ、学習を発散させずに進めたい場面。", "opt": ["正解。経験再生はデータの偏りを減らし、ターゲットネットワークは目標値を計算する側を一定間隔固定して更新の振動を抑える。", "経験再生とターゲットネットワークの役割が入れ替わっている。過去の経験をため込むのは経験再生、目標値側を固定するのはターゲットネットワークである。", "これはマルチエージェント学習の説明であり、経験再生・ターゲットネットワークとは別の工夫。", "これは報酬成形の説明であり、経験再生・ターゲットネットワークとは別の工夫。"]}'),

  ('g-kentei-h-q48', '6. ディープラーニングの応用例',
   'ダブルDQN、デュエリングネットワーク、Rainbowの関係として、最も適切なものはどれか。',
   NULL::text,
   '["ダブルDQNやデュエリングネットワークはDQNの弱点を個別に改良した手法であり、Rainbowはそれらの複数の改良を組み合わせた集大成的な手法である。", "Rainbowが最初に提案された元祖の手法であり、ダブルDQNとデュエリングネットワークはRainbowを個別の要素に後から分解しただけの手法である。", "ダブルDQN、デュエリングネットワーク、Rainbowは、いずれもQ値を経由せず方策を直接改善する、DQNとは無関係な方策勾配系の強化学習手法である。", "ダブルDQN、デュエリングネットワーク、Rainbowは、いずれも過学習を抑えるための教師あり学習の正則化手法である。"]',
   0,
   '[0]',
   'single',
   '{"asked": "ダブルDQN・デュエリングネットワークという個別の改良と、それらをまとめたRainbowという集大成の関係を問うている。", "point": "個別の改良(ダブルDQN・デュエリング)→それらを合わせた集大成(Rainbow)、という順番。", "why_asked": "DQNの改良系列は名前が似た手法が多く、どれが個別の改良でどれがそれらをまとめたものかを取り違えやすいから。", "kid": "ダブルDQNとデュエリングネットワークは、それぞれDQNの弱点を1つずつ直す工夫。Rainbowはそういう工夫を何個もまとめて全部乗せにした「良いとこ取り」の手法。", "eg": "自転車の改良で例えると、ダブルDQNは「ブレーキの利きを良くする改良」、デュエリングネットワークは「サドルを乗りやすくする改良」のような個別の改良で、Rainbowはそれらの改良を全部盛り込んだ完成形の自転車、というイメージ。", "terms": [["ダブルDQN(Double DQN)", "行動選択と価値評価に別々のネットワークを使い、Q値の過大評価を抑えるDQNの改良"], ["デュエリングネットワーク(Dueling Network)", "状態そのものの価値と行動ごとの得の違いを分けて推定するDQNの改良"], ["Rainbow", "ダブルDQNやデュエリングネットワークなど複数の改良を組み合わせた手法"]], "think": "DQNには「Q値を過大評価しやすい」「状態の価値と行動の価値を区別できない」といった複数の弱点があり、ダブルDQNやデュエリングネットワークはそれぞれ1つの弱点にピンポイントで対処する改良として個別に提案された。Rainbowはこうした個別の改良(経験再生の優先度付けなども含む)をまとめて1つのモデルに詰め込み、それぞれの改良を組み合わせた効果を検証した集大成的な手法。", "vs": "A3CやPPOのような方策勾配系の手法とは系統が違い、ダブルDQN・デュエリングネットワーク・RainbowはいずれもQ値を推定するDQN系列の改良である点を混同しない。", "usecase": "ゲームAIの性能をできるだけ高めたい研究・開発の場面で、複数の改良を積み上げる設計の考え方の参考になる。", "opt": ["正解。ダブルDQNやデュエリングネットワークは個別の改良であり、Rainbowはそれらを組み合わせた集大成的な手法である。", "元祖と派生の関係が逆になっている。ダブルDQNとデュエリングネットワークが個別の改良として先にあり、Rainbowはそれらをまとめたものである。", "これは方策勾配系(A3CやPPOなど)の説明であり、ダブルDQN・デュエリングネットワーク・RainbowはいずれもQ値を推定するDQN系列の手法である。", "これは教師あり学習の正則化の説明であり、強化学習の手法であるこの3つとは無関係。"]}'),

  ('g-kentei-h-q49', '6. ディープラーニングの応用例',
   'A3CやPPOのような方策勾配系の強化学習手法の位置づけとして、最も適切なものはどれか。',
   NULL::text,
   '["Q値を経由せず、行動を選ぶ方策そのものを直接改善していく手法群であり、PPOは生成AIを人間の好みに沿って調整するRLHFでもよく使われる。", "Q値をテーブルやニューラルネットワークで近似し、その値の高さをもとに行動を選ぶ、ダブルDQNやRainbowと同じDQN系列の手法群である。", "A3CもPPOも、教師あり学習でラベル付きデータから正解のラベルを直接予測する、画像分類のような分類や回帰の手法である。", "A3CもPPOも、画像を段階的に縮めてから元の大きさに戻して塗り分ける、セマンティックセグメンテーションの手法である。"]',
   0,
   '[0]',
   'single',
   '{"asked": "A3CやPPOが「方策を直接改善する」方策勾配系の手法であり、Q値を経由するDQN系とは別系統であることを問うている。", "point": "方策勾配系は「行動の選び方そのもの」を直接良くしていく手法群。", "why_asked": "DQN系(Q値を推定)と方策勾配系(方策を直接改善)は同じ強化学習でも仕組みが違い、名前が並ぶと混同しやすいから。特にPPOはRLHFでの使われ方が実務で頻出するテーマだから。", "kid": "DQNは「この行動をとったらどれくらい良いか(点数)」を予想してから行動を選ぶのに対し、A3CやPPOは「どの行動を選ぶか」という判断の仕方そのものを、報酬が増える方向へ直接練習していく。", "eg": "DQN系は「この手を打ったら何点入るか」を予想する採点表を作ってから一番点の高い手を選ぶ将棋の考え方。方策勾配系は採点表を経由せず、「こう指すと良い結果になりやすい」という指し方そのものを、経験を通じて直接上達させていく考え方。", "terms": [["方策勾配法(Policy Gradient)", "行動を選ぶ方策そのものを直接、報酬が増える方向へ改善していく手法群"], ["A3C(Asynchronous Advantage Actor-Critic)", "複数のエージェントを非同期に並行して学習させる方策勾配系の手法"], ["PPO(Proximal Policy Optimization＝近接方策最適化)", "方策の更新幅を大きく変えすぎないよう抑えながら安定して学習する手法。RLHFでもよく使われる"]], "think": "DQN系はまず「状態と行動の組み合わせの価値(Q値)」を推定し、その値が最も高い行動を選ぶという間接的なやり方をとる。これに対しA3CやPPOのような方策勾配系は、Q値を経由せず「どの行動をどれくらいの確率で選ぶか」という方策そのものを、報酬が増える方向へ勾配を使って直接更新していく。PPOはこの更新幅が大きくなりすぎないよう抑える工夫を持ち、大規模言語モデルを人間の評価に沿って調整するRLHFの中でもよく使われている。", "vs": "ダブルDQN・デュエリングネットワーク・Rainbowは全てQ値を推定するDQN系列の改良であり、A3C・PPOのような方策を直接改善する系統とは異なるグループである点を混同しない。", "usecase": "連続的な行動(ロボットの関節の動きなど)を扱う制御や、大規模言語モデルを人間の好みに沿って調整するRLHFの場面。", "opt": ["正解。Q値を経由せず方策そのものを直接改善する手法群で、PPOはRLHFでもよく使われる。", "これはDQNのようにQ値を推定してから行動を選ぶ系統の説明であり、方策勾配系のA3C・PPOとは仕組みが異なる。", "これは教師あり学習の説明であり、報酬を手がかりに試行錯誤する強化学習であるA3C・PPOとは学習の枠組みが異なる。", "これはセグメンテーションの説明であり、強化学習の手法であるA3C・PPOとは全く無関係。"]}'),

  ('g-kentei-h-q50', '6. ディープラーニングの応用例',
   'DCGAN、CycleGAN、Pix2Pixの違いとして、最も適切なものはどれか。',
   NULL::text,
   '["DCGANは生成器と識別器を畳み込みで組んだ基本形、Pix2Pixは対応するペア画像を使って変換を学ぶ手法、CycleGANはペアが無いデータどうしでも変換を学べる手法である。", "DCGANはペアが無いデータどうしの変換を学ぶ手法、Pix2Pixは生成器と識別器を畳み込みで組んだ基本形、CycleGANは対応するペア画像を使って変換を学ぶ手法である、という対応関係になっている。", "DCGAN、CycleGAN、Pix2Pixは、いずれもノイズを段階的に取り除いて高品質な画像を生成する、Diffusion Modelのような拡散モデルの一種にすぎない。", "DCGAN、CycleGAN、Pix2Pixは、いずれも画像とテキストのペアを大量に学習して同じ意味空間に埋め込む、CLIPのようなマルチモーダルの手法にすぎない。"]',
   0,
   '[0]',
   'single',
   '{"asked": "GANファミリーであるDCGAN(基本形)・Pix2Pix(ペアあり変換)・CycleGAN(ペアなし変換)を正しく対応づけられるかを問うている。", "point": "「畳み込みの基本形／ペアで変換／ペア無しで変換」の3役をそれぞれ正しく当てはめる。", "why_asked": "GANの応用系はどれも「生成」という共通点で語られやすく、それぞれの新規性(畳み込み化・対応の有無)を区別できるかが頻出の引っかけだから。", "kid": "DCGANはGANの基本形。Pix2Pixは「線画→写真」のように対応するペアの画像を見て変換を覚える。CycleGANはペアが無くても「馬の写真」と「シマウマの写真」のように似た者同士なら変換を覚えられる。", "eg": "Pix2Pixは対応する見本(線画とその完成写真のセット)を見ながら描き方を学ぶ絵の練習。CycleGANは対応する見本が無くても、「馬らしさ」と「シマウマらしさ」の特徴だけを見比べて、変換の仕方を独学で編み出すようなもの。", "terms": [["DCGAN(Deep Convolutional GAN)", "生成器と識別器の両方を畳み込みネットワークで組んだ、GANの基本形"], ["Pix2Pix", "対応するペア画像(線画→写真など)を使って画像変換を学ぶ手法"], ["CycleGAN", "対応するペアが無いデータどうし(馬↔シマウマなど)でも変換を学べる手法"]], "think": "GANは元々「生成器と識別器を競わせる」という枠組みだけを示すもので、DCGANはこれを畳み込みネットワークで具体的に組んだ基本形にあたる。Pix2Pixはこの枠組みを画像変換に応用し、入力と出力が1対1に対応するペアのデータ(線画とその写真など)で学習する。CycleGANはペアの用意が難しい場面向けに、対応関係が無いデータどうしでも「変換して戻すと元に近づく」という仕組み(サイクル一貫性)を使って変換を学べるようにした。", "vs": "Pix2Pixは「ペアが必要」、CycleGANは「ペアが不要」という対応関係の有無が最大の違い。DCGANはそもそも画像変換ではなく、GANを畳み込みで実装した基本形である点を混同しない。", "usecase": "Pix2Pixは設計図から完成予想図を作る用途、CycleGANは写真を絵画風に変換するなど対になる学習データが用意しにくい用途で使われる。", "opt": ["正解。DCGANは畳み込みによる基本形、Pix2Pixはペア画像を使う変換、CycleGANはペア無しでも変換を学べる手法である。", "DCGANとCycleGANの説明が入れ替わっている。畳み込みの基本形はDCGAN、ペア無しの変換はCycleGANである。", "これは拡散モデル(Diffusion Model)の説明であり、DCGAN・CycleGAN・Pix2Pixとは仕組みが異なる。", "これはCLIPのようなマルチモーダル手法の説明であり、画像どうしの変換を行うこの3つとは対象が異なる。"], "viz": "<svg viewBox=\"0 0 340 150\" xmlns=\"http://www.w3.org/2000/svg\" font-family=\"sans-serif\"><defs><marker id=\"arr\" markerWidth=\"6\" markerHeight=\"6\" refX=\"5\" refY=\"3\" orient=\"auto\"><path d=\"M0,0 L6,3 L0,6 Z\" fill=\"#8892a4\"/></marker></defs><text x=\"170\" y=\"12\" fill=\"#e8eaf0\" font-size=\"10\" text-anchor=\"middle\" font-weight=\"600\">同じGANでも「何を」学ぶかが違う</text><text x=\"55\" y=\"28\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">DCGAN</text><rect x=\"20\" y=\"36\" width=\"60\" height=\"22\" rx=\"4\" fill=\"none\" stroke=\"#60a5fa\" stroke-width=\"1.3\"/><text x=\"50\" y=\"51\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">生成器</text><line x1=\"50\" y1=\"60\" x2=\"50\" y2=\"76\" stroke=\"#8892a4\" stroke-width=\"1.3\" marker-end=\"url(#arr)\"/><rect x=\"20\" y=\"78\" width=\"60\" height=\"22\" rx=\"4\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.3\"/><text x=\"50\" y=\"93\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">識別器</text><text x=\"50\" y=\"112\" fill=\"#8892a4\" font-size=\"7.5\" text-anchor=\"middle\">畳み込みの基本形</text><line x1=\"120\" y1=\"20\" x2=\"120\" y2=\"138\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><text x=\"180\" y=\"28\" fill=\"#60a5fa\" font-size=\"9.5\" text-anchor=\"middle\" font-weight=\"600\">Pix2Pix</text><rect x=\"150\" y=\"50\" width=\"55\" height=\"26\" rx=\"4\" fill=\"none\" stroke=\"#8892a4\" stroke-width=\"1.3\"/><text x=\"177\" y=\"67\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">線画</text><line x1=\"207\" y1=\"63\" x2=\"233\" y2=\"63\" stroke=\"#6ab08d\" stroke-width=\"1.3\" marker-end=\"url(#arr)\"/><rect x=\"235\" y=\"50\" width=\"55\" height=\"26\" rx=\"4\" fill=\"none\" stroke=\"#6ab08d\" stroke-width=\"1.3\"/><text x=\"262\" y=\"67\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">写真</text><text x=\"215\" y=\"96\" fill=\"#8892a4\" font-size=\"7.5\" text-anchor=\"middle\">対応するペアで変換を学習</text><line x1=\"300\" y1=\"20\" x2=\"300\" y2=\"138\" stroke=\"#2a2f3f\" stroke-width=\"1.3\"/><text x=\"170\" y=\"118\" fill=\"#c9a04a\" font-size=\"8.5\" text-anchor=\"middle\">CycleGAN：ペアが無くても双方向に変換を学べる</text><rect x=\"80\" y=\"122\" width=\"55\" height=\"24\" rx=\"4\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.3\"/><text x=\"107\" y=\"138\" fill=\"#e8eaf0\" font-size=\"8\" text-anchor=\"middle\">馬</text><path d=\"M138 130 C 160 122, 190 122, 210 130\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.3\" marker-end=\"url(#arr)\"/><path d=\"M210 136 C 190 144, 160 144, 138 136\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.3\" marker-end=\"url(#arr)\"/><rect x=\"212\" y=\"122\" width=\"55\" height=\"24\" rx=\"4\" fill=\"none\" stroke=\"#c9a04a\" stroke-width=\"1.3\"/><text x=\"239\" y=\"138\" fill=\"#e8eaf0\" font-size=\"7.5\" text-anchor=\"middle\">シマウマ</text></svg>"}')


) AS v(source_ref, category_name, question_text, code, options,
       correct_index, correct_indices, question_type, explanation_data)
  ON c.name = v.category_name AND s.slug = 'g-kentei-h'
ON CONFLICT (subject_id, source_ref) DO NOTHING;

COMMIT;
